static void test_l95_syntax_100(void) {
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_syntax("\"<reSolutIOn>  |STRETCH  |<inteGeR>\t|\t-MOZ-THING+| <resolution> | <IMAGE>#+#|<ANGLE>\"", 85));
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_syntax_parse("\"<reSolutIOn>  |STRETCH  |<inteGeR>\t|\t-MOZ-THING+| <resolution> | <IMAGE>#+#|<ANGLE>\"", 85, &g_p));
    TEST_ASSERT_EQUAL(0, g_p.nalt);
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_syntax("\" <INTEGER> | < url>| <angLe>+\"", 31));
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_syntax_parse("\" <INTEGER> | < url>| <angLe>+\"", 31, &g_p));
    TEST_ASSERT_EQUAL(0, g_p.nalt);
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_syntax("\"<length-percentage>+\t|\t<transform-function>#\t|\t<tiMe>#|<resolution>|nOne++\"", 76));
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_syntax_parse("\"<length-percentage>+\t|\t<transform-function>#\t|\t<tiMe>#|<resolution>|nOne++\"", 76, &g_p));
    TEST_ASSERT_EQUAL(0, g_p.nalt);
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax("\" left-side#\"", 13));
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax_parse("\" left-side#\"", 13, &g_p));
    TEST_ASSERT_EQUAL(1, g_p.nalt);
    alt_is(0, WF_CSSPROP_KEYWORD, 2, "left-side");
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax("'THIN+\t|\tnone+|<PERCENTAGE>  |<RESOLUTION>+ '", 45));
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax_parse("'THIN+\t|\tnone+|<PERCENTAGE>  |<RESOLUTION>+ '", 45, &g_p));
    TEST_ASSERT_EQUAL(4, g_p.nalt);
    alt_is(0, WF_CSSPROP_KEYWORD, 1, "thin");
    alt_is(1, WF_CSSPROP_KEYWORD, 1, "none");
    alt_is(2, WF_CSSPROP_PERCENT, 0, "");
    alt_is(3, WF_CSSPROP_RESOLUTION, 1, "");
}

static void test_l95_syntax_101(void) {
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_syntax("' <COLOR> | <image>#  |STrEtch+  |<urls> '", 42));
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_syntax_parse("' <COLOR> | <image>#  |STrEtch+  |<urls> '", 42, &g_p));
    TEST_ASSERT_EQUAL(0, g_p.nalt);
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax("\" <NUMBER>|LEFT-SIDE  |<iNteGER>+ | <TIME>#  |A1#| <percentage>  |<length-percentage>\"", 86));
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax_parse("\" <NUMBER>|LEFT-SIDE  |<iNteGER>+ | <TIME>#  |A1#| <percentage>  |<length-percentage>\"", 86, &g_p));
    TEST_ASSERT_EQUAL(7, g_p.nalt);
    alt_is(0, WF_CSSPROP_NUMBER, 0, "");
    alt_is(1, WF_CSSPROP_KEYWORD, 0, "left-side");
    alt_is(2, WF_CSSPROP_INTEGER, 1, "");
    alt_is(3, WF_CSSPROP_TIME, 2, "");
    alt_is(4, WF_CSSPROP_KEYWORD, 2, "a1");
    alt_is(5, WF_CSSPROP_PERCENT, 0, "");
    alt_is(6, WF_CSSPROP_LENPCT, 0, "");
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_syntax("\" <nUMber>+ | a#b\t|\t<ANGLE>#\t|\t<number>\"", 40));
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_syntax_parse("\" <nUMber>+ | a#b\t|\t<ANGLE>#\t|\t<number>\"", 40, &g_p));
    TEST_ASSERT_EQUAL(0, g_p.nalt);
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax("\"X\t|\t<STRING>#  |<TIME>\"", 24));
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax_parse("\"X\t|\t<STRING>#  |<TIME>\"", 24, &g_p));
    TEST_ASSERT_EQUAL(3, g_p.nalt);
    alt_is(0, WF_CSSPROP_KEYWORD, 0, "x");
    alt_is(1, WF_CSSPROP_STRING, 2, "");
    alt_is(2, WF_CSSPROP_TIME, 0, "");
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax("\"<uRl>+ | <resolution>\"", 23));
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax_parse("\"<uRl>+ | <resolution>\"", 23, &g_p));
    TEST_ASSERT_EQUAL(2, g_p.nalt);
    alt_is(0, WF_CSSPROP_URL, 1, "");
    alt_is(1, WF_CSSPROP_RESOLUTION, 0, "");
}

static void test_l95_syntax_102(void) {
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax("' <rEsolution>#'", 16));
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax_parse("' <rEsolution>#'", 16, &g_p));
    TEST_ASSERT_EQUAL(1, g_p.nalt);
    alt_is(0, WF_CSSPROP_RESOLUTION, 2, "");
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax("'<number>| <length>\t|\t<COLOR>  |<TRANSFORM-LIST>\t|\t<length>#'", 61));
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax_parse("'<number>| <length>\t|\t<COLOR>  |<TRANSFORM-LIST>\t|\t<length>#'", 61, &g_p));
    TEST_ASSERT_EQUAL(5, g_p.nalt);
    alt_is(0, WF_CSSPROP_NUMBER, 0, "");
    alt_is(1, WF_CSSPROP_LENGTH, 0, "");
    alt_is(2, WF_CSSPROP_COLOR, 0, "");
    alt_is(3, WF_CSSPROP_TLIST, 0, "");
    alt_is(4, WF_CSSPROP_LENGTH, 2, "");
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax("'<LENGTH>#  |<Length-peRcENtage>  |<number>#| <LENGTH>|<STRING>  |<RESOLUTION>#|<angle>#\t|\t_under#'", 99));
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax_parse("'<LENGTH>#  |<Length-peRcENtage>  |<number>#| <LENGTH>|<STRING>  |<RESOLUTION>#|<angle>#\t|\t_under#'", 99, &g_p));
    TEST_ASSERT_EQUAL(8, g_p.nalt);
    alt_is(0, WF_CSSPROP_LENGTH, 2, "");
    alt_is(1, WF_CSSPROP_LENPCT, 0, "");
    alt_is(2, WF_CSSPROP_NUMBER, 2, "");
    alt_is(3, WF_CSSPROP_LENGTH, 0, "");
    alt_is(4, WF_CSSPROP_STRING, 0, "");
    alt_is(5, WF_CSSPROP_RESOLUTION, 2, "");
    alt_is(6, WF_CSSPROP_ANGLE, 2, "");
    alt_is(7, WF_CSSPROP_KEYWORD, 2, "_under");
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax("\"<STRING>#\"", 11));
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax_parse("\"<STRING>#\"", 11, &g_p));
    TEST_ASSERT_EQUAL(1, g_p.nalt);
    alt_is(0, WF_CSSPROP_STRING, 2, "");
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_syntax("' BIG+++ '", 10));
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_syntax_parse("' BIG+++ '", 10, &g_p));
    TEST_ASSERT_EQUAL(0, g_p.nalt);
}

static void test_l95_syntax_103(void) {
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax("\"<custom-ident># \"", 18));
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax_parse("\"<custom-ident># \"", 18, &g_p));
    TEST_ASSERT_EQUAL(1, g_p.nalt);
    alt_is(0, WF_CSSPROP_CIDENT, 2, "");
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax("' a1#|<image>\t|\t<urL># | <aNGLe>\t|\t<Url>+| <IMAGE>'", 51));
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax_parse("' a1#|<image>\t|\t<urL># | <aNGLe>\t|\t<Url>+| <IMAGE>'", 51, &g_p));
    TEST_ASSERT_EQUAL(6, g_p.nalt);
    alt_is(0, WF_CSSPROP_KEYWORD, 2, "a1");
    alt_is(1, WF_CSSPROP_IMAGE, 0, "");
    alt_is(2, WF_CSSPROP_URL, 2, "");
    alt_is(3, WF_CSSPROP_ANGLE, 0, "");
    alt_is(4, WF_CSSPROP_URL, 1, "");
    alt_is(5, WF_CSSPROP_IMAGE, 0, "");
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_syntax("\" <LENGTH># | <image>\t|\tNONE# | auTO+| <RESolution>#| <RESOLUTION> | <PERCENTAGE>\t|\t<nUMbeR>+| <RESOLUTION>|<ANGLE> \"", 117));
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_syntax_parse("\" <LENGTH># | <image>\t|\tNONE# | auTO+| <RESolution>#| <RESOLUTION> | <PERCENTAGE>\t|\t<nUMbeR>+| <RESOLUTION>|<ANGLE> \"", 117, &g_p));
    TEST_ASSERT_EQUAL(0, g_p.nalt);
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax("'<intEGer>| <transform-function>+ | none+|<cusTOm-idEnt> | <url>+  |AUTO | <percenTaGE>  |<color>+ '", 100));
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax_parse("'<intEGer>| <transform-function>+ | none+|<cusTOm-idEnt> | <url>+  |AUTO | <percenTaGE>  |<color>+ '", 100, &g_p));
    TEST_ASSERT_EQUAL(8, g_p.nalt);
    alt_is(0, WF_CSSPROP_INTEGER, 0, "");
    alt_is(1, WF_CSSPROP_TFUNC, 1, "");
    alt_is(2, WF_CSSPROP_KEYWORD, 1, "none");
    alt_is(3, WF_CSSPROP_CIDENT, 0, "");
    alt_is(4, WF_CSSPROP_URL, 1, "");
    alt_is(5, WF_CSSPROP_KEYWORD, 0, "auto");
    alt_is(6, WF_CSSPROP_PERCENT, 0, "");
    alt_is(7, WF_CSSPROP_COLOR, 1, "");
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax("' <pErcEntage># | <INteger>+\t|\t<lEngtH>#  |<tranSForm-lIst>  |<STRinG>\t|\t<STRING>+ | <tIMe> '", 93));
    TEST_ASSERT_EQUAL(WF_CSSPROP_COMPLEX, wf_cssprop_syntax_parse("' <pErcEntage># | <INteger>+\t|\t<lEngtH>#  |<tranSForm-lIst>  |<STRinG>\t|\t<STRING>+ | <tIMe> '", 93, &g_p));
    TEST_ASSERT_EQUAL(7, g_p.nalt);
    alt_is(0, WF_CSSPROP_PERCENT, 2, "");
    alt_is(1, WF_CSSPROP_INTEGER, 1, "");
    alt_is(2, WF_CSSPROP_LENGTH, 2, "");
    alt_is(3, WF_CSSPROP_TLIST, 0, "");
    alt_is(4, WF_CSSPROP_STRING, 0, "");
    alt_is(5, WF_CSSPROP_STRING, 1, "");
    alt_is(6, WF_CSSPROP_TIME, 0, "");
}

